package org.apache.commons.math3.optimization.univariate;

import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.exception.TooManyEvaluationsException;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.InitialGuess;
import org.apache.commons.math3.optimization.MaxEval;
import org.apache.commons.math3.optimization.SimpleUnivariateValueChecker;
import org.apache.commons.math3.optimization.univariate.BrentOptimizer;
import org.apache.commons.math3.optimization.univariate.UnivariatePointValuePair;
import org.junit.Assert;
import org.junit.Test;

public class AgentBRT_Math_23_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Define a simple quadratic function: f(x) = (x - 2)^2
        UnivariateFunction function = new UnivariateFunction() {
            @Override
            public double value(double x) {
                return (x - 2) * (x - 2);
            }
        };

        // Create a BrentOptimizer instance with reasonable thresholds
        BrentOptimizer optimizer = new BrentOptimizer(1e-10, 1e-14);

        // Set up the optimization problem
        UnivariatePointValuePair result = optimizer.optimize(
            new MaxEval(1000),
            new org.apache.commons.math3.optimization.univariate.UnivariateObjectiveFunction(function),
            GoalType.MINIMIZE,
            new org.apache.commons.math3.optimization.univariate.SearchInterval(0, 4),
            new InitialGuess(0)
        );

        // The expected minimum is at x = 2 with f(x) = 0
        Assert.assertEquals(2.0, result.getPoint(), 1e-8);
        Assert.assertEquals(0.0, result.getValue(), 1e-8);
    }
}

